static const struct { const char *id, *file, *text; } kw_landings[] = {
	{"future", "LAND_FUTURE.RAW", "Ship computer:\n\nYou have now landed in the\nShadowlands.\nIt is thirty two years later.\nKeen is old.\nI am older.\nPlease walk slowly."},
	{"revival", "LAND_REVIVAL.RAW", "Ship computer:\n\nYou have now landed on Aurora\nBliss.\nAgain.\nAllain is turning the whole\nplanet into one machine.\nCraig is here too.\nPlease keep him away from my\nNavi-Com."},
	{"revivalc", "LAND_REVIVALC.RAW", "Ship computer:\n\nYou have now landed on Aurora\nBliss.\nAgain.\nCaptain Craig, I hear your\npogo stick is broken.\nPlease do not fix it with my\nparts."},
	{"saint", "LAND_SAINT.RAW", "Ship computer:\n\nYou have now landed on Aurora\nBliss, in the mountains.\nThree months have gone by.\nCraig is buried here.\nI will wait.\nTake your time."},
	{"party", "LAND_PARTY.RAW", "Ship computer:\n\nYou have now landed in the\nShadowlands.\nThere is a party at the Tower\nof Dusk.\nYou are late.\nAgain."},
	{"canmore", "LAND_CANMORE.RAW", "Ship computer:\n\nYou have now landed on Azura\nAstrid.\nThe pilot was Craig Canmore.\nI did not agree to this.\nKeen and Mortimer are tied up\nin the back, and they are not\nhappy.\nCraig, go and find your\nsister."},
	{"ocflore", "LAND_OCFLORE.RAW", "Ship computer:\n\nYou have now landed on Ocflore\nV.\nBeware of the local water.\nThere is a lot of it.\nThe Ormch are waiting to meet\nyou.\nI do not trust them."},
	{"aurora", "LAND_AURORA.RAW", "Ship computer:\n\nYou have now landed on Aurora\nBliss.\nAnd here we stay.\nMy Navi-Com is sticky with\nVorta Cola, and I cannot take\noff.\nPlease find the spare parts,\nand do not let Craig touch\nanything."},
	{"rtts", "LAND_RTTS.RAW", "Ship computer:\n\nYou have now landed in the far\nShadowlands.\nBeware of the local scouts.\nThey are lost, they are\nhungry, and they all want your\nautograph."},
	{"suburb", "LAND_SUBURB.RAW", "Ship computer:\n\nYou have now landed on Earth.\nYour own street.\nI am parked by the backyard\nclubhouse.\nPlease try to catch the bus\nthis time."},
	{"alpham", "LAND_ALPHAM.RAW", "Ship computer:\n\nYou have now docked at the\nAlphamatic.\nVitaCorp's bigger armageddon\nmachine.\nPlease switch it off before we\nleave."},
	{"keen4", "LAND_KEEN4.RAW", "Ship computer:\n\nYou have now landed on\nGnosticus IV.\nBeware of the local slugs.\nThey are poisonous, and they\nwill not say sorry."},
	{"keen5", "LAND_KEEN5.RAW", "Ship computer:\n\nYou have now docked at the\nOmegamatic.\nBeware of the local robots.\nThey have lasers, and no sense\nof humour."},
	{"keen6", "LAND_KEEN6.RAW", "Ship computer:\n\nYou have now landed on\nFribbulus Xax.\nBeware of the local Bloogs.\nThey are big, they are green,\nand it is always lunch time."},
	{"keen7", "LAND_KEEN7.RAW", "Ship computer:\n\nYou have now landed on\nKrodacia.\nBeware of the local\nKrodacians.\nThey collect keys.\nAnd visitors."},
	{"keen8", "LAND_KEEN8.RAW", "Ship computer:\n\nYou have now landed on\nCalidune.\nBeware of the local desert.\nAll of it.\nPlease drink some water."},
	{"keen9", "LAND_KEEN9.RAW", "Ship computer:\n\nYou have now docked at the HUB\nCommand Center.\nBeware of the local Mortimer.\nHe is one IQ point smarter\nthan you, and he will mention\nit."},
	{"arealm", "LAND_AREALM.RAW", "Ship computer:\n\nYou have now crashed on\nKrisle.\nBeware of the local Atroxians.\nAlso, the ship is broken.\nThis was not my fault."},
	{"keen95", "LAND_KEEN95.RAW", "Ship computer:\n\nYou have now landed on\nGnosticus IV.\nAgain.\nBeware of the local explosion.\nSomething has taken the\nOracle's batteries, and it was\nnot me."},
	{"ck55", "LAND_CK55.RAW", "Ship computer:\n\nYou have now docked at the\nOmegamatic II.\nBeware of the local robots.\nThey are the same robots, but\nsomebody has updated them."},
	{"asylum", "LAND_ASYLUM.RAW", "Ship computer:\n\nYou have now landed at an\naddress unknown.\nBeware of the local level\ndesign.\nSomebody built this place for\nfun, and it was not your fun."},
	{"bounty", "LAND_BOUNTY.RAW", "Ship computer:\n\nYou have now landed on\nMeurglys III.\nBeware of the local wildlife.\nAnd the local Elvis.\nAlso, somebody has written\nwash me on my side."},
	{"osi", "LAND_OSI.RAW", "Ship computer:\n\nYou have now docked at the\nShikadi Station.\nBeware of the local Shikadi.\nThey are made of electricity,\nand they hold a grudge."},
	{"fitf", "LAND_FITF.RAW", "Ship computer:\n\nYou have now landed on\nGnosticus Pi.\nBeware of the local trees.\nSome of them are not trees."},
};
